import{z as n,x as s,o as l,c as p,q as B,j as o,D as e,d as r,s as A,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"引用模型与 KL 的管理","description":"","frontmatter":{"title":"引用模型与 KL 的管理","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rlsys-refmodel-kl.md","filePath":"llm/rlsys-refmodel-kl.md","lastUpdated":1791413859000}'),m={name:"llm/rlsys-refmodel-kl.md"};function C(d,E,h,_,F,D){const t=s("Mermaid");return l(),p("div",null,[E[2]||(E[2]=B('<h1 id="引用模型与-kl-的管理" tabindex="-1">引用模型与 KL 的管理 <a class="header-anchor" href="#引用模型与-kl-的管理" aria-label="Permalink to &quot;引用模型与 KL 的管理&quot;">​</a></h1><div class="epigraph"><p>引用模型是训练里唯一不许变的那块权重：它不产生梯度，却定义了整个跑道的边界。</p><footer>—— 据 Schulman 等 2017（PPO）的 KL 惩罚设计与 Schulman 2016 的 KL 近似笔记整理</footer></div><p><a href="/llm/rlsys-reward-serving">上一课</a>把打分做成服务，经验三件套齐了：序列、行为 logprob、奖励。本课补训练相最安静的角色——引用模型：冻结的初始策略，给出 KL 的参照分布。它不学一个参数，却占一份显存、付一份前向，还要回答一个算法问题：KL 到底挂在奖励里、挂在损失里，还是根本不挂。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>KL 正则把当前策略 \\(\\pi_\\theta\\) 拉向 \\(\\pi_{\\mathrm{ref}}\\)，防止它离开数据支撑太远——这是<a href="/llm/ppo-kl-value">KL 惩罚与价值函数</a>的算法面。系统面的问题是同一件事的三种挂法各有不同的账单。折进奖励（InstructGPT 式的 \\(r_t \\gets r_t - \\beta\\,\\mathrm{KL}_t\\)）：引用前向必须发生在 rollout 相，每个样本多一遍 teacher forcing 前向。折进训练损失：引用前向挪到训练相，与梯度计算分时共享卡。完全不挂（<a href="/llm/kl-free-rl">无 KL 的 RL</a>）：引用模型整块不加载，显存立省一份，但漂移只剩 clip 与早停拦着。选哪种不只是算法口味，而是显存与吞吐预算的分配——这正是它进「架构」单元的原因。</p><p><span class="marginnote">「引用模型」\\(\\pi_{\\mathrm{ref}}\\) 就是出发点的快照：通常是 SFT 刚结束时的那份权重，整个训练期间冻结不动。它唯一的职责是当参照物——每步回答「现在的策略离出发时偏了多远」，这个偏离量就是 KL。它自己一个参数也不更新。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>无论挂哪，估计用低方差的那支。对采样自 \\(\\pi_\\theta\\) 的 token，取比值 \\(r = \\pi_{\\mathrm{ref}}/\\pi_\\theta\\)，用 \\(k_3 = r - \\log r - 1\\)：其期望恰为 \\(\\mathrm{KL}(\\pi_\\theta \\,\\|\\, \\pi_{\\mathrm{ref}})\\)，且逐点非负、方差远小于直接平均 \\(\\log r\\)；方向别接反，分母是行为侧。工程要点三条。第一，引用前向只需在已采样的 token 上取 logprob——不生成、不扫词表，成本是一次 teacher forcing 前向，可与 rollout 相共享批处理。第二，引用 logprob 与行为 logprob 同样要缓存并带版本：复用旧样本做离策略修正时，KL 的分子要用打分当时的 \\(\\pi_\\theta\\)，不是最新版。第三，显存管理：引用模型可常驻、可 offload 到 CPU 按需搬入、可在无 KL 配置下整个不加载；共置布局里它是第三个模型，与训练器、rollout 引擎抢峰值显存。</p><p><span class="marginnote">数字实例看 \\(k_3\\) 的非负性：取 \\(r=2\\)（参考概率是行为概率的两倍），\\(k_3=2-\\log 2-1\\approx0.31\\)；取 \\(r=0.5\\)，\\(k_3=0.5-\\log 0.5-1\\approx0.19\\)。比值无论大于还是小于 1，结果都不为负——这是它能当 KL 估计量的好处之一；直接平均 \\(\\log r\\) 则正负不定、方差大。</span></p><p><span class="marginnote">\\(k_3 = r - \\log r - 1\\) 的期望等于 KL，靠的是 \\(\\mathbb{E}_{\\pi_\\theta}[r] = 1\\) 这条性质；换一个 token 分布（例如在温度缩放后的分布上取比值），期望就不再是 KL，而是一个不知名的量。</span></p>',10)),(l(),o(i,null,{default:e(()=>[A(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E9%87%87%E6%A0%B7%20token%20%E5%BA%8F%E5%88%97%22%5D%20--%3E%20FWD%5B%22%E5%BC%95%E7%94%A8%E6%A8%A1%E5%9E%8B%20teacher%20forcing%20%E5%89%8D%E5%90%91%EF%BC%88%E5%86%BB%E7%BB%93%E6%9D%83%E9%87%8D%EF%BC%89%22%5D%0A%20%20FWD%20--%3E%20K%5B%22%E9%80%90%20token%20KL%EF%BC%9Ak3%20%E4%BC%B0%E8%AE%A1%22%5D%0A%20%20K%20--%3E%7C%E6%8A%98%E8%BF%9B%E5%A5%96%E5%8A%B1%7C%20RW%5B%22%E5%A5%96%E5%8A%B1%E5%88%97%EF%BC%9Ar_t%20%E5%87%8F%20%CE%B2%C2%B7KL_t%EF%BC%88rollout%20%E7%9B%B8%EF%BC%89%22%5D%0A%20%20K%20--%3E%7C%E6%8A%98%E8%BF%9B%E6%8D%9F%E5%A4%B1%7C%20LW%5B%22%E6%8D%9F%E5%A4%B1%E9%A1%B9%EF%BC%9A%CE%B2%C2%B7KL%EF%BC%88%E8%AE%AD%E7%BB%83%E7%9B%B8%EF%BC%89%22%5D%0A%20%20K%20--%3E%7C%E4%B8%8D%E6%8C%82%7C%20FREE%5B%22%E6%97%A0%20KL%EF%BC%9A%E5%8D%B8%E8%BD%BD%E5%BC%95%E7%94%A8%E6%A8%A1%E5%9E%8B%EF%BC%8C%E9%9D%A0%20clip%20%E4%B8%8E%E6%97%A9%E5%81%9C%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[r("KL 挂在哪里，决定它是「奖励的一部分」还是「约束的一部分」，监控语义随之不同。折进奖励时，KL 是代理奖励的组成部分，优化器会主动权衡它——调小 \\(\\beta\\) 等于放宽跑道，"),a("a",{href:"/llm/reward-overoptimization-theory"},"奖励过优化的理论视角"),r("里它正是压力旋钮；折进损失时它更像信赖域的软实现，两种挂法的曲线要分开解读。两条路都要求把每步 KL 统计量记进监控：均值突跳通常是策略在大规模偏离（可能是 hack，也可能是崩溃前兆），缓缓爬升是正常探索。无 KL 配置下这根仪表没了，漂移监控改由评测与熵承担——省下的显存买走了一根最重要的仪表，这笔交易要显式记账。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：KL 惩罚像风筝线——线放得长（\\(\\beta\\) 小），风筝飞得高、探索得远；线收得太紧，风筝贴地打转什么也采不到；完全剪断（无 KL）飞得最爽，但一头栽下来时没有任何东西拦着。三种挂法（折进奖励 / 折进损失 / 不挂）只是把「收线的手」装在不同位置。")],-1)),(l(),o(i,null,{default:e(()=>[A(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E6%AF%8F%E6%AD%A5%20KL%20%E7%BB%9F%E8%AE%A1%E9%87%8F%EF%BC%88%E5%B8%A6%E7%89%88%E6%9C%AC%EF%BC%89%22%5D%20--%3E%20S%7B%22%E6%9B%B2%E7%BA%BF%E5%BD%A2%E6%80%81%EF%BC%9F%22%7D%0A%20%20S%20--%3E%7C%22%E5%B9%B3%E7%BC%93%E7%88%AC%E5%8D%87%22%7C%20EXP%5B%22%E6%AD%A3%E5%B8%B8%E6%8E%A2%E7%B4%A2%EF%BC%9A%E8%AE%B0%E5%BD%95%E5%8D%B3%E5%8F%AF%22%5D%0A%20%20S%20--%3E%7C%22%E5%9D%87%E5%80%BC%E7%AA%81%E8%B7%B3%22%7C%20JUMP%5B%22%E5%A4%A7%E8%A7%84%E6%A8%A1%E5%81%8F%E7%A6%BB%EF%BC%9A%E6%9F%A5%20hack%20%E6%88%96%E5%B4%A9%E6%BA%83%E5%89%8D%E5%85%86%22%5D%0A%20%20S%20--%3E%7C%22%E8%B4%B4%E5%9C%B0%E4%B8%8D%E5%8A%A8%22%7C%20LOCK%5B%22%E5%8F%AF%E8%83%BD%E9%94%81%E6%AD%BB%E6%88%96%E7%BA%A6%E6%9D%9F%E8%BF%87%E7%B4%A7%EF%BC%9A%E6%9F%A5%E7%86%B5%22%5D%0A%20%20JUMP%20--%3E%20ACT%5B%22%E6%8A%A5%E8%AD%A6%EF%BC%9A%E5%9B%9E%E6%BB%9A%E6%88%96%E6%94%B6%E7%B4%A7%20%CE%B2%22%5D%0A%20%20LOCK%20--%3E%20ACT2%5B%22%E6%A3%80%E6%9F%A5%E6%8E%A2%E7%B4%A2%E8%83%BD%E5%8A%9B%EF%BC%9A%E6%B8%A9%E5%BA%A6%20%2F%20%E7%86%B5%E4%BB%AA%E8%A1%A8%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>引用模型管理不提供对齐保证：KL 小只代表离起点近，不代表好；KL 的支撑性质保证不了内容质量。\\(\\pi_{\\mathrm{ref}}\\) 选哪个快照（SFT 末、某轮 RL 前）本身是超参，换参照点等价于换跑道，跨实验比较时必须同参照。多轮迭代里「上一轮产物当下轮参照」会让参照本身漂移，跑道随训练移动，这个边界条件要写进配方而不是留在实现里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>引用模型是冻结权重，只付前向不付梯度；三种挂法（奖励/损失/无）对应三份显存与吞吐账单。</li><li>KL 估计用 \\(k_3 = r - \\log r - 1\\)：期望即 KL、逐点非负、低方差；方向是 \\(\\pi_{\\mathrm{ref}}/\\pi_\\theta\\)。</li><li>引用 logprob 只在采样 token 上取，需缓存并带版本；复用旧样本时分母取打分当时版本。</li><li>KL 曲线是核心仪表：突跳查 hack 或崩溃，缓升是探索；无 KL 配置拿掉它要换仪表。</li><li>出处：Schulman 等 2017（PPO）；Schulman 2016（KL 近似笔记）；据 InstructGPT 与开源框架实现整理。</li></ul>',4))])}const f=n(m,[["render",C]]);export{L as __pageData,f as default};
